import{_ as i,o as a,c as n,a4 as l}from"./chunks/framework.B-wJupoK.js";const c=JSON.parse('{"title":"24-函数重载","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/24-函数重载/24-函数重载.md","filePath":"仓颉入门到实战/24-函数重载/24-函数重载.md","lastUpdated":1735170666000,"__rawMarkdown":"# 24-函数重载\\n\\n## 函数重载定义\\n\\n在仓颉编程语言中，如果一个作用域中，**一个函数名对应多个函数定义**，这种现象称为函数重载。\\n\\n### 函数名相同，函数参数不同\\n\\n是指参数个数不同，或者参数个数相同但参数类型不同）的两个函数构成重载。示例如下：\\n\\n```javascript\\n// Scenario 1\\nfunc f(a: Int64): Unit {\\n}\\n\\nfunc f(a: Float64): Unit {\\n}\\n\\nfunc f(a: Int64, b: Float64): Unit {\\n}\\n```\\n\\n### 泛型函数，泛型函数不同\\n\\n对于两个同名泛型函数，如果重命名一个函数的泛型形参后，其非泛型部分与另一个函数的非泛型部分函数参数不同，则两个函数构成重\\n\\n载，否则这两个泛型函数构成重复定义错误（类型变元的约束不参与判断）。示例如下：\\n\\n```javascript\\ninterface I1{}\\ninterface I2{}\\n\\nfunc f1<X, Y>(a: X, b: Y) {}\\nfunc f1<Y, X>(a: X, b: Y) {} // Ok: a b 部分不同\\n\\nfunc f2<T>(a: T) where T <: I1 {}\\nfunc f2<T>(a: T) where T <: I2 {} // Error, 泛型其他部分相同\\n```\\n\\n### 一个类内的两个构造函数参数不同\\n\\n```javascript\\n// Scenario 2\\nclass C {\\n    var a: Int64\\n    var b: Float64\\n\\n    public init(a: Int64, b: Float64) {\\n        this.a = a\\n        this.b = b\\n    }\\n\\n    public init(a: Int64) {\\n        b = 0.0\\n        this.a = a\\n    }\\n}\\n```\\n\\n### 主构造函数和 init 构造函数参数\\n\\n```javascript\\n// Scenario 3\\nclass C {\\n    C(var a!: Int64, var b!: Float64) {\\n        this.a = a\\n        this.b = b\\n    }\\n\\n    public init(a: Int64) {\\n        b = 0.0\\n        this.a = a\\n    }\\n}\\n\\n```\\n\\n### 两个函数定义在不同的作用域\\n\\n```javascript\\n// Scenario 4\\nfunc f(a: Int64): Unit {\\n}\\n\\nfunc g() {\\n    func f(a: Float64): Unit {\\n    }\\n}\\n\\n```\\n\\n\\n\\n### 两个函数分别定义在父类和子类中\\n\\n```javascript\\n// Scenario 5\\nopen class Base {\\n    public func f(a: Int64): Unit {\\n    }\\n}\\n\\nclass Sub <: Base {\\n    public func f(a: Float64): Unit {\\n    }\\n}\\n\\n```\\n\\n## 不构成重载的情况\\n\\n- class、interface、struct 类型的静态成员函数和实例成员函数之间不能重载\\n- enum 类型的 constructor、静态成员函数和实例成员函数之间不能重载\\n\\n如下示例，两个变量均为函数类型且函数参数类型不同，但由于它们不是函数声明所以不能重载，如下示例将编译报错（重定义错）：\\n\\n```javascript\\nmain() {\\n    var f: (Int64) -> Unit\\n    var f: (Float64) -> Unit\\n}\\n```\\n\\n如下示例，虽然变量 `f` 为函数类型，但由于变量和函数之间不能同名，如下示例将编译报错（重定义错）：\\n\\n```javascript\\nmain() {\\n    var f: (Int64) -> Unit\\n\\n    func f(a: Float64): Unit {   // Error, functions and variables cannot have the same name.\\n    }\\n}\\n```\\n\\n如下示例，静态成员函数 `f` 与实例成员函数 `f` 的参数类型不同，但由于类内静态成员函数和实例成员函数之间不能重载，如下示例将编译报错：\\n\\n```javascript\\nclass C {\\n    public static func f(a: Int64): Unit {\\n    }\\n    public func f(a: Float64): Unit {\\n    }\\n}\\n```\\n\\n## 函数重载决议\\n\\n函数调用时，所有可被调用的函数（是指当前作用域可见且能通过类型检查的函数）构成候选集，候选集中有多个函数，究竟选择候选集中哪个函数，需要进行函数重载决议，有如下规则：\\n\\n- 优先选择作用域级别高的作用域内的函数。在嵌套的表达式或函数中，越是内层作用域级别越高。\\n\\n  如下示例中在 `inner` 函数体内调用 `g(Sub())` 时，候选集包括 `inner` 函数内定义的函数 `g` 和 `inner` 函数外定义的函数 `g`，函数决议选择作用域级别更高的 `inner` 函数内定义的函数 `g`。\\n\\n  ```javascript\\n  open class Base {}\\n  class Sub <: Base {}\\n  \\n  func outer() {\\n      func g(a: Sub) {\\n          print(\\"1\\")\\n      }\\n  \\n      func inner() {\\n          func g(a: Base) {\\n              print(\\"2\\")\\n          }\\n  \\n          g(Sub())   // Output: 2\\n      }\\n  }\\n  ```\\n\\n- 如果作用域级别相对最高的仍有多个函数，则需要选择最匹配的函数（对于函数 f 和 g 以及给定的实参，如果 f 可以被调用时 g 也总是可以被调用的，但反之不然，则我们称 f 比 g 更匹配）。如果不存在唯一最匹配的函数，则报错。\\n\\n  如下示例中，两个函数 `g` 定义在同一作用域，选择更匹配的函数 `g(a: Sub): Unit`。\\n\\n  ```javascript\\n  open class Base {}\\n  class Sub <: Base {}\\n  \\n  func outer() {\\n      func g(a: Sub) {\\n          print(\\"1\\")\\n      }\\n      func g(a: Base) {\\n          print(\\"2\\")\\n      }\\n  \\n      g(Sub())   // Output: 1\\n  \\n  }\\n  ```\\n\\n- 子类和父类认为是同一作用域。如下示例中，一个函数 `g` 定义在父类中，另一个函数 `g` 定义在子类中，在调用 `s.g(Sub())` 时，两个函数 `g` 当成同一作用域级别决议，则选择更匹配的父类中定义的函数 `g(a: Sub): Unit`。\\n\\n  ```javascript\\n  open class Base {\\n      public func g(a: Sub) { print(\\"1\\") }\\n  }\\n  \\n  class Sub <: Base {\\n      public func g(a: Base) {\\n          print(\\"2\\")\\n      }\\n  }\\n  \\n  func outer() {\\n      let s: Sub = Sub()\\n      s.g(Sub())   // Output: 1\\n  }\\n  ```"}'),p={name:"仓颉入门到实战/24-函数重载/24-函数重载.md"};function h(k,s,t,e,r,E){return a(),n("div",null,[...s[0]||(s[0]=[l("",29)])])}const g=i(p,[["render",h]]);export{c as __pageData,g as default};
